import{c,$ as o,Q as l,j as s,g as t,n as r,o as a,m as n}from"./chunks/framework.Xjf2pjgg.js";const k=JSON.parse('{"title":"YuRelic 插件联动","description":"","frontmatter":{"title":"YuRelic 插件联动"},"headers":[],"relativePath":"plugins/items/yu-relic/api.md","filePath":"plugins/items/yu-relic/api.md"}'),p={name:"plugins/items/yu-relic/api.md"},u={class:"quick-actions"};function h(m,e,y,g,b,_){const d=o("CopyMarkdownButton"),i=o("CopyLLMButton");return l(),s("div",null,[e[0]||(e[0]=t("h1",{id:"yurelic-插件联动",tabindex:"-1"},[r("YuRelic 插件联动 "),t("a",{class:"header-anchor",href:"#yurelic-插件联动","aria-label":'Permalink to "YuRelic 插件联动"'},"​")],-1)),t("div",u,[a(d,{page:""}),a(i,{page:""})]),e[1]||(e[1]=n('<p>本页保留跨插件联动总览。权限、PlaceholderAPI 和 Bukkit 事件已拆到独立页面，日常查表可以直接进入对应章节。</p><div class="doc-card-grid"><a class="doc-mini-card" href="/plugins/items/yu-relic/permissions"><strong>权限节点</strong><span>玩家、系统、管理、高危操作与倍率权限</span></a><a class="doc-mini-card" href="/plugins/items/yu-relic/placeholders"><strong>PlaceholderAPI</strong><span>灵器状态、开光、面板和天榜变量</span></a><a class="doc-mini-card" href="/plugins/items/yu-relic/events"><strong>Bukkit 事件</strong><span>开光、成长、战斗、资源、市场和天榜监听</span></a><a class="doc-mini-card" href="/plugins/items/yu-relic/commands"><strong>命令手册</strong><span>玩家、管理员与运维命令</span></a></div><h2 id="软依赖与联动" tabindex="-1">软依赖与联动 <a class="header-anchor" href="#软依赖与联动" aria-label="Permalink to &quot;软依赖与联动&quot;">​</a></h2><p>YuRelic 在 <code>plugin.yml</code> 中声明的软依赖：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LevelledMobs, MythicMobs, WorldGuard, WorldEdit, Vault, PlayerPoints, EasyBot, PlaceholderAPI</span></span></code></pre></div><p>这些插件不存在时，YuRelic 不应阻断启动。用 <code>/yurelic hooks</code> 可以看到当前服务端的联动状态。</p><table tabindex="0"><thead><tr><th>插件</th><th>典型用途</th></tr></thead><tbody><tr><td><code>PlaceholderAPI</code></td><td>将灵器等级、评分、器体、天榜等信息显示到菜单、计分板或聊天。</td></tr><tr><td><code>Vault</code> / <code>PlayerPoints</code></td><td>开光、修复、仪式、商店等经济成本。</td></tr><tr><td><code>LevelledMobs</code> / <code>MythicMobs</code></td><td>灵材掉落、怪物等级和副本生态联动。</td></tr><tr><td><code>WorldGuard</code> / <code>WorldEdit</code></td><td>区域倍率、掉落限制、战斗场景和副本区域判断。</td></tr><tr><td><code>EasyBot</code></td><td>将开光、觉醒、入藏、天榜等事件广播到外部机器人。</td></tr></tbody></table><h2 id="easybot-与广播" tabindex="-1">EasyBot 与广播 <a class="header-anchor" href="#easybot-与广播" aria-label="Permalink to &quot;EasyBot 与广播&quot;">​</a></h2><p>YuRelic 的广播系统支持游戏内 MiniMessage、控制台纯文本、EasyBot RPC 和玩家聊天兜底。典型 payload 包含：</p><ul><li><code>action</code>：事件类型。</li><li><code>message</code>：MiniMessage 文本。</li><li><code>plain</code>：去色纯文本。</li><li><code>player</code>、<code>item</code>、<code>relic</code>、<code>quality</code>、<code>id</code>、<code>short_id</code>。</li><li><code>placeholders</code>：完整占位符表。</li></ul><p>如果 EasyBot RPC 不可用，可以让广播走玩家聊天路径，方便 QQ 桥按普通玩家消息捕获。游戏内 hover/click 组件与 QQ 纯文本转发天然不同，跨平台公告建议保留短文本版本。</p><h2 id="集成建议" tabindex="-1">集成建议 <a class="header-anchor" href="#集成建议" aria-label="Permalink to &quot;集成建议&quot;">​</a></h2><ul><li>活动倍率、VIP 加成、区域规则优先监听 <code>RelicGainExpEvent</code>。</li><li>竞技场、职业插件、领地插件优先监听 <code>RelicCombatModifyEvent</code> 或使用场景规则配置。</li><li>自定义掉落与副本结算优先监听 <code>RelicLootResourceEvent</code>。</li><li>经济插件不要直接改 NBT，优先调用命令或监听仪式、资源、市场事件。</li><li>高危操作如归炉、传承、清理、软锁裁定，应保留管理员权限与审计链。</li></ul>',13))])}const v=c(p,[["render",h]]);export{k as __pageData,v as default};
